// eslint-disable-next-line no-control-regex
const ANSI_ESCAPE_REGEX = /\x1B\[[0-9;]*m/g;

// The debug banner that the Vitest addon prepends to error messages.
// See code/addons/vitest/src/vitest-plugin/setup-file.ts
const DEBUG_BANNER_TEXT = 'Click to debug the error directly in Storybook';

/**
 * Removes any Storybook debug banner (and its ANSI color codes) from a message, so that the
 * underlying error message is preserved.
 */
function stripDebugBanner(text: string): string {
  return text
    .replace(ANSI_ESCAPE_REGEX, '')
    .split('\n')
    .filter((line) => !line.includes(DEBUG_BANNER_TEXT))
    .join('\n');
}

/** Returns the first line of a string that is not empty once trimmed, or undefined if none exists. */
function firstNonEmptyLine(text: string): string | undefined {
  return text
    .split('\n')
    .map((line) => line.trim())
    .find((line) => line.length > 0);
}

