export function extractCategorizedErrors(testResults: StoryTestResult[]): {
  totalErrors: number;
  uniqueErrorCount: number;
  categorizedErrors: Record<
    string,
    { count: number; uniqueCount: number; matchedDependencies: string[] }
  >;
